-- ================================================-- 018 - 彻底修复所有角色权限-- ================================================-- 查看当前角色权限SELECT r.code, p.code as perm_code, p.name as perm_name, p.pathFROM roles rJOIN role_permissions rp ON r.id = rp.role_idJOIN permissions p ON rp.permission_id = p.idWHERE r.code IN ('admin', 'viewer', 'temp_auditor', 'temp_chairman')  AND p.type = 'menu'ORDER BY r.code, p.sort_order;-- 删除所有非admin角色的管理类菜单权限DELETE FROM role_permissionsWHERE role_id IN (SELECT id FROM roles WHERE code IN ('viewer', 'temp_auditor', 'temp_chairman'))  AND permission_id IN (SELECT id FROM permissions WHERE code IN (    'menu:users',    'menu:roles',    'menu:categories',    'menu:ingredient-manager',    'menu:departments',    'menu:wecom',    'menu:purchase-entry',    'menu:reimbursement',    'menu:temp-positions',    'menu:temp-workers' ));-- 确保管理员拥有所有菜单权限INSERT INTO role_permissions (role_id, permission_id)SELECT r.id, p.idFROM roles rCROSS JOIN permissions pWHERE r.code = 'admin'  AND p.type = 'menu'  AND p.status = 1  AND NOT EXISTS (    SELECT 1 FROM role_permissions rp     WHERE rp.role_id = r.id AND rp.permission_id = p.id  );-- 确保查看员只有查看类菜单INSERT INTO role_permissions (role_id, permission_id)SELECT r.id, p.idFROM roles rJOIN permissions p ON p.code IN ('menu:daily', 'menu:monthly', 'menu:yearly', 'menu:ingredients')WHERE r.code = 'viewer'  AND p.type = 'menu'  AND p.status = 1  AND NOT EXISTS (    SELECT 1 FROM role_permissions rp     WHERE rp.role_id = r.id AND rp.permission_id = p.id  );-- 确保外请审核员只有外请人员相关菜单INSERT INTO role_permissions (role_id, permission_id)SELECT r.id, p.idFROM roles rJOIN permissions p ON p.code IN ('menu:temp-audit', 'menu:temp-assessment', 'menu:temp-stats', 'menu:daily')WHERE r.code = 'temp_auditor'  AND p.type = 'menu'  AND p.status = 1  AND NOT EXISTS (    SELECT 1 FROM role_permissions rp     WHERE rp.role_id = r.id AND rp.permission_id = p.id  );-- 确保外请董事长只有查看类菜单INSERT INTO role_permissions (role_id, permission_id)SELECT r.id, p.idFROM roles rJOIN permissions p ON p.code IN ('menu:temp-stats', 'menu:daily')WHERE r.code = 'temp_chairman'  AND p.type = 'menu'  AND p.status = 1  AND NOT EXISTS (    SELECT 1 FROM role_permissions rp     WHERE rp.role_id = r.id AND rp.permission_id = p.id  );-- 验证修复结果SELECT r.code as role_code, r.name as role_name, p.code as perm_code, p.name as perm_name, p.pathFROM roles rJOIN role_permissions rp ON r.id = rp.role_idJOIN permissions p ON rp.permission_id = p.idWHERE r.code IN ('admin', 'viewer', 'temp_auditor', 'temp_chairman')  AND p.type = 'menu'ORDER BY r.code, p.sort_order;SELECT '018_fix_all_permissions.sql 执行完成' AS message;